struct TA_CHOPTR_Stream {
   /* The bars this handle has an output for (see TA_CHOPTR_OutRange). */
   int outRangeBegIdx;
   int outRangeCount;
   /* The value(s) at the last bar the stream counted (see TA_CHOPTR_Value). */
   double cur_outReal;
   int optInTimePeriod;
   double logPeriod;
   int winPos_i;
   int winCap_i;
   double *win_i_inHigh;
   double *win_i_inLow;
   double *win_i_inClose;
};

/* Private function, not in public API. */
static void TA_CHOPTR_ReleaseImpl( struct TA_CHOPTR_Stream *sp )
{
   if( !sp ) return;
   if( sp->win_i_inHigh ) TA_Free( sp->win_i_inHigh );
   if( sp->win_i_inLow ) TA_Free( sp->win_i_inLow );
   if( sp->win_i_inClose ) TA_Free( sp->win_i_inClose );
   TA_Free( sp );
}

/* Private function, not in public API. */
static void TA_CHOPTR_StepImpl( struct TA_CHOPTR_Stream *sp, double inHigh, double inLow, double inClose, double *outReal )
{
   int i;
   double highest;
   double lowest;
   double sumTR;
   double tempHT;
   double tempLT;
   double prevClose;
   double trueHigh;
   double trueLow;

   sp->win_i_inHigh[sp->winPos_i] = inHigh;
   sp->win_i_inLow[sp->winPos_i] = inLow;
   sp->win_i_inClose[sp->winPos_i] = inClose;
   /* Re-summed oldest to newest every bar, never a running total: a
    * running total leaves a residue on a window of zero true ranges, which
    * the exact guard below would then read as a trend.
    */
   highest = inHigh;
   lowest = inLow;
   sumTR = 0.0;
   prevClose = 0.0;
   for( i = sp->optInTimePeriod; i >= 0; i -= 1 )
   {
      if( i < sp->optInTimePeriod )
      {
         tempHT = sp->win_i_inHigh[(sp->winPos_i + sp->winCap_i - i >= sp->winCap_i) ? sp->winPos_i + sp->winCap_i - i - sp->winCap_i : sp->winPos_i + sp->winCap_i - i];
         tempLT = sp->win_i_inLow[(sp->winPos_i + sp->winCap_i - i >= sp->winCap_i) ? sp->winPos_i + sp->winCap_i - i - sp->winCap_i : sp->winPos_i + sp->winCap_i - i];
         trueHigh = tempHT;
         if( prevClose > trueHigh )
         {
            trueHigh = prevClose;
         }
         trueLow = tempLT;
         if( prevClose < trueLow )
         {
            trueLow = prevClose;
         }
         sumTR += trueHigh - trueLow;
         if( trueHigh > highest )
         {
            highest = trueHigh;
         }
         if( trueLow < lowest )
         {
            lowest = trueLow;
         }
      }
      prevClose = sp->win_i_inClose[(sp->winPos_i + sp->winCap_i - i >= sp->winCap_i) ? sp->winPos_i + sp->winCap_i - i - sp->winCap_i : sp->winPos_i + sp->winCap_i - i];
   }
   /* The seeds are the raw extrema of today's bar, which its own true
    * high and low always enclose, so they never outrun the true box.
    *
    * Exact test, never an epsilon band (issue #253). Every true range lies
    * inside the box, so a positive sum implies a positive box. Keep the
    * "<=" form: a NaN sum must fall through to the log, not read as 100.
    * Keep the parenthesised quotient: it returns exactly 100 whenever the
    * computed ratio is exactly the period.
    */
   if( sumTR <= 0.0 )
   {
      *outReal= 100.0;
   } else 
   {
      *outReal= 100.0 * (log10(sumTR / (highest - lowest)) / sp->logPeriod);
   }
   sp->cur_outReal = *outReal;
   sp->winPos_i = sp->winPos_i + 1;
   if( sp->winPos_i >= sp->winCap_i )
   {
      sp->winPos_i = 0;
   }
}

static TA_RetCode TA_CHOPTR_OpenImpl( struct TA_CHOPTR_Stream **stream, const double inHigh[], const double inLow[], const double inClose[], int startIdx, int historyLen, int optInTimePeriod, int *outBegIdx, int *outNBElement, double outReal[], int outStride )
{
   struct TA_CHOPTR_Stream *sp;
   int endIdx;

   if( !stream ) return TA_BAD_PARAM;
   *stream = NULL;
   if( historyLen < 1 ) return TA_OUT_OF_RANGE_START_INDEX;
   if( historyLen > TA_INDEX_MAX + 1 ) return TA_OUT_OF_RANGE_END_INDEX;
   if( !inHigh || !inLow || !inClose || !outReal ) return TA_BAD_PARAM;
   if( (int)optInTimePeriod == TA_INTEGER_DEFAULT )
      optInTimePeriod = 14;
   else if( (int)optInTimePeriod < 2 || (int)optInTimePeriod > 100000 )
      return TA_BAD_PARAM;
   if( startIdx > historyLen - 1 )
   {
      *outBegIdx = 0;
      *outNBElement = 0;
      return TA_INSUFFICIENT_HISTORY;
   }

   endIdx = historyLen - 1;

   {
      int today;
      int outIdx;
      int lookbackTotal;
      int i;
      double highest;
      double lowest;
      double sumTR;
      double logPeriod = 0.0;
      double tempHT;
      double tempLT;
      double prevClose;
      double trueHigh;
      double trueLow;
      *outBegIdx= 0;
      *outNBElement= 0;
      lookbackTotal = TA_CHOPTR_Lookback(optInTimePeriod);
      if( startIdx < lookbackTotal )
      {
         startIdx = lookbackTotal;
      }
      /* Make sure there is still something to evaluate. */
      if( startIdx > endIdx )
      {
         return TA_INSUFFICIENT_HISTORY;
      }
      logPeriod = log10((double)optInTimePeriod);
      outIdx = 0;
      today = startIdx;
      while( today <= endIdx )
      {
         /* Re-summed oldest to newest every bar, never a running total: a
          * running total leaves a residue on a window of zero true ranges, which
          * the exact guard below would then read as a trend.
          */
         highest = inHigh[today];
         lowest = inLow[today];
         sumTR = 0.0;
         prevClose = 0.0;
         for( i = optInTimePeriod; i >= 0; i -= 1 )
         {
            if( i < optInTimePeriod )
            {
               tempHT = inHigh[today - i];
               tempLT = inLow[today - i];
               trueHigh = tempHT;
               if( prevClose > trueHigh )
               {
                  trueHigh = prevClose;
               }
               trueLow = tempLT;
               if( prevClose < trueLow )
               {
                  trueLow = prevClose;
               }
               sumTR += trueHigh - trueLow;
               if( trueHigh > highest )
               {
                  highest = trueHigh;
               }
               if( trueLow < lowest )
               {
                  lowest = trueLow;
               }
            }
            prevClose = inClose[today - i];
         }
         /* The seeds are the raw extrema of today's bar, which its own true
          * high and low always enclose, so they never outrun the true box.
          *
          * Exact test, never an epsilon band (issue #253). Every true range lies
          * inside the box, so a positive sum implies a positive box. Keep the
          * "<=" form: a NaN sum must fall through to the log, not read as 100.
          * Keep the parenthesised quotient: it returns exactly 100 whenever the
          * computed ratio is exactly the period.
          */
         if( sumTR <= 0.0 )
         {
            outReal[outIdx * outStride] = 100.0;
         } else 
         {
            outReal[outIdx * outStride] = 100.0 * (log10(sumTR / (highest - lowest)) / logPeriod);
         }
         outIdx += 1;
         today += 1;
      }
      *outBegIdx= startIdx;
      *outNBElement= outIdx;

      /* Capture the live batch state into the handle. */
      sp = (struct TA_CHOPTR_Stream *)TA_Malloc( sizeof(*sp) );
      if( !sp ) { return TA_ALLOC_ERR; }
      memset( sp, 0, sizeof(*sp) );
      sp->optInTimePeriod = optInTimePeriod;
      sp->logPeriod = logPeriod;
      sp->winCap_i = (int)(optInTimePeriod + 1);
      if( sp->winCap_i < 1 || sp->winCap_i > historyLen ) { TA_CHOPTR_ReleaseImpl( sp ); return TA_INTERNAL_ERROR(457); }
      sp->win_i_inHigh = (double *)TA_Malloc( sizeof(double) * (size_t)sp->winCap_i );
      if( !sp->win_i_inHigh ) { TA_CHOPTR_ReleaseImpl( sp ); return TA_ALLOC_ERR; }
      memcpy( sp->win_i_inHigh, inHigh + (historyLen - sp->winCap_i), sizeof(double) * (size_t)sp->winCap_i );
      sp->win_i_inLow = (double *)TA_Malloc( sizeof(double) * (size_t)sp->winCap_i );
      if( !sp->win_i_inLow ) { TA_CHOPTR_ReleaseImpl( sp ); return TA_ALLOC_ERR; }
      memcpy( sp->win_i_inLow, inLow + (historyLen - sp->winCap_i), sizeof(double) * (size_t)sp->winCap_i );
      sp->win_i_inClose = (double *)TA_Malloc( sizeof(double) * (size_t)sp->winCap_i );
      if( !sp->win_i_inClose ) { TA_CHOPTR_ReleaseImpl( sp ); return TA_ALLOC_ERR; }
      memcpy( sp->win_i_inClose, inClose + (historyLen - sp->winCap_i), sizeof(double) * (size_t)sp->winCap_i );
      sp->winPos_i = 0;
      sp->outRangeBegIdx = *outBegIdx;
      sp->outRangeCount = *outNBElement;
      sp->cur_outReal = outReal[(*outNBElement - 1) * outStride];
      *stream = sp;
      return TA_SUCCESS;
   }
}

